INSERT INTO `persons` (`id`, `first_names`, `last_name`, `birth_name`, `nickname`, `gender`, `is_living`, `birth_date`, `birth_approx`, `birth_place`, `death_date`, `death_approx`, `death_place`, `death_cause`, `burial_place`, `occupation`, `nationality`, `religion`, `education`, `residence`, `hobbies`, `phone`, `email`, `biography`, `anecdotes`, `notes`, `photo_id`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`, `deleted_by`) VALUES (5,'Joseph Marcel','Laurent',NULL,'Pépé Jo','M',0,'1910-03-21',0,'Saint-Flour','1985-11-02',0,'Aurillac',NULL,NULL,'Forgeron','Française',NULL,NULL,'Saint-Flour, puis Aurillac','Pêche à la truite, accordéon',NULL,NULL,'Fils aîné de Louis et Jeanne, Joseph apprend le métier de forgeron dès 14 ans chez son oncle.\n\nMobilisé en 1939, il est fait prisonnier en 1940 et passe quatre ans dans une ferme en Allemagne. À son retour, il ouvre sa propre forge à Aurillac, qui deviendra le point de rendez-vous de tout le quartier.','Il jouait de l\'accordéon à chaque mariage de la famille, même à 70 ans passés.',NULL,NULL,NULL,NULL,'2026-11-20 03:02:50','2026-11-20 03:02:50',NULL,NULL);
